const page = await figma.getNodeByIdAsync('5:2');
const home = await figma.getNodeByIdAsync('13:83');
const hb = home.absoluteBoundingBox;
const region = {x:hb.x+1008, y:hb.y+3080, w:432, h:428};
const hits=[];
function walk(n, inHome){
  if(n.absoluteBoundingBox){
    const b=n.absoluteBoundingBox;
    const ov = b.x < region.x+region.w && b.x+b.width > region.x && b.y < region.y+region.h && b.y+b.height > region.y;
    if(ov && !inHome){
      hits.push({id:n.id,name:n.name,type:n.type,x:Math.round(b.x-hb.x),y:Math.round(b.y-hb.y),w:Math.round(b.width),h:Math.round(b.height)});
    }
  }
  if(n.children) n.children.forEach(c=>walk(c, inHome || n.id===home.id));
}
page.children.forEach(c=>walk(c,false));
return JSON.stringify({homeBox:{x:hb.x,y:hb.y,w:Math.round(hb.width),h:Math.round(hb.height)},hits:hits.slice(0,30),total:hits.length});
